"use client";

import React from "react";
import { Header } from "./Header";
import { ConversationPanel } from "../conversation/ConversationPanel";
import { PipelineOverview } from "../rag/PipelineOverview";
import { TelemetryPanel } from "../telemetry/TelemetryPanel";
import { DeveloperPanel } from "../developer/DeveloperPanel";
import { useRAGSessionStore } from "@/stores/ragSessionStore";
import { SlidersHorizontal, Activity, Code2, MessageSquare } from "lucide-react";

export const AppShell: React.FC = () => {
  const developerMode = useRAGSessionStore((state) => state.developerMode);
  const activeMobileTab = useRAGSessionStore((state) => state.activeMobileTab);
  const [rightPanelTab, setRightPanelTab] = React.useState<"pipeline" | "telemetry" | "developer">("pipeline");

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans selection:bg-indigo-500 selection:text-white">
      {/* Global Header */}
      <Header />

      {/* Main Responsive Grid Layout */}
      <main className="flex-1 max-w-[1700px] w-full mx-auto p-3 sm:p-4 md:p-6 overflow-hidden">
        {/* Desktop View (1024px and above) */}
        <div className="hidden lg:grid grid-cols-12 gap-6 h-[calc(100vh-110px)]">
          {/* Left Column: Conversation & Input (7 Columns ~58-65%) */}
          <div className="col-span-7 xl:col-span-7 flex flex-col h-full overflow-hidden bg-slate-950">
            <ConversationPanel />
          </div>

          {/* Right Column: Control Room / Telemetry / Dev Panel (5 Columns ~35-42%) */}
          <div className="col-span-5 xl:col-span-5 flex flex-col h-full bg-slate-950 border-l border-slate-800/80 pl-6 overflow-y-auto space-y-4">
            {/* Panel Tab Selector Header */}
            <div className="sticky top-0 bg-slate-950 z-20 pb-2 border-b border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-1 bg-slate-900 p-1 rounded-lg border border-slate-800 text-xs font-medium">
                <button
                  onClick={() => setRightPanelTab("pipeline")}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md transition-colors ${
                    rightPanelTab === "pipeline"
                      ? "bg-indigo-600 text-white font-bold shadow"
                      : "text-slate-400 hover:text-slate-200"
                  }`}
                >
                  <SlidersHorizontal className="w-3.5 h-3.5" />
                  RAG Pipeline
                </button>

                <button
                  onClick={() => setRightPanelTab("telemetry")}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md transition-colors ${
                    rightPanelTab === "telemetry"
                      ? "bg-indigo-600 text-white font-bold shadow"
                      : "text-slate-400 hover:text-slate-200"
                  }`}
                >
                  <Activity className="w-3.5 h-3.5" />
                  Telemetry
                </button>

                <button
                  onClick={() => setRightPanelTab("developer")}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md transition-colors ${
                    rightPanelTab === "developer"
                      ? "bg-indigo-600 text-white font-bold shadow"
                      : "text-slate-400 hover:text-slate-200"
                  }`}
                >
                  <Code2 className="w-3.5 h-3.5" />
                  Dev Console
                </button>
              </div>
            </div>

            {/* Right Panel Content */}
            <div className="flex-1 overflow-y-auto pr-1">
              {developerMode || rightPanelTab === "developer" ? (
                <DeveloperPanel />
              ) : rightPanelTab === "telemetry" ? (
                <TelemetryPanel />
              ) : (
                <PipelineOverview />
              )}
            </div>
          </div>
        </div>

        {/* Mobile & Tablet View (below 1024px) */}
        <div className="block lg:hidden h-[calc(100vh-140px)]">
          {activeMobileTab === "chat" && (
            <div className="h-full">
              <ConversationPanel />
            </div>
          )}

          {activeMobileTab === "pipeline" && (
            <div className="h-full overflow-y-auto">
              <PipelineOverview />
            </div>
          )}

          {activeMobileTab === "telemetry" && (
            <div className="h-full overflow-y-auto">
              <TelemetryPanel />
            </div>
          )}

          {activeMobileTab === "developer" && (
            <div className="h-full overflow-y-auto">
              <DeveloperPanel />
            </div>
          )}
        </div>
      </main>
    </div>
  );
};
